<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,defineAsyncComponent} from 'vue';
const SpatialScene=defineAsyncComponent(()=>import('./SpatialScene.vue'));const props=defineProps({node:Object,theme:Object,playing:Boolean,assets:Object,interactive:Boolean});const emit=defineEmits(['action']);const host=ref(),error=ref(''),poi=ref(null);let map,observer,frame,last=0;const configured=computed(()=>!!props.node.props.mapToken);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
async function init(){if(!configured.value||!host.value)return;error.value='';try{const {default:mapboxgl}=await import('mapbox-gl');await import('mapbox-gl/dist/mapbox-gl.css');if(!host.value)return;const p=props.node.props;map=new mapboxgl.Map({container:host.value,accessToken:p.mapToken,style:p.mapStyle,center:[p.lng,p.lat],zoom:p.zoom,pitch:p.pitch,bearing:p.bearing,interactive:props.interactive,antialias:true,attributionControl:true});map.on('style.load',()=>{if(p.dem&&!map.getSource('astra-dem')){map.addSource('astra-dem',{type:'raster-dem',url:'mapbox://mapbox.mapbox-terrain-dem-v1',tileSize:512,maxzoom:14});map.setTerrain({source:'astra-dem',exaggeration:1.5});}if(p.buildings&&map.getSource('composite')&&!map.getLayer('astra-buildings')){map.addLayer({id:'astra-buildings',source:'composite','source-layer':'building',filter:['==','extrude','true'],type:'fill-extrusion',minzoom:14,paint:{'fill-extrusion-color':props.theme.accent,'fill-extrusion-height':['coalesce',['get','height'],8],'fill-extrusion-base':['coalesce',['get','min_height'],0],'fill-extrusion-opacity':.45}});}map.setFog({color:props.theme.bg,'high-color':props.theme.bg,'space-color':props.theme.bg,'horizon-blend':.08});});map.on('error',e=>error.value=e.error?.message?.includes('access token')?'Mapbox Token 无效，请检查授权域名与权限':'地图资源加载失败，请检查 Token、网络与样式地址');map.on('click',e=>{const features=map.queryRenderedFeatures(e.point),feature=features.find(f=>f.properties?.name)||features[0];const row={name:feature?.properties?.name||'地图选中区域',lng:e.lngLat.lng,lat:e.lngLat.lat,...feature?.properties};poi.value=row;map.flyTo({center:[row.lng,row.lat],zoom:Math.max(16,map.getZoom()),duration:1400});emit('action','click',row);});observer=new ResizeObserver(()=>map?.resize());observer.observe(host.value);function cruise(now){frame=requestAnimationFrame(cruise);if(document.hidden||!props.playing||!p.autoRotate||reduced||now-last<50||map.isMoving())return;last=now;map.rotateTo(map.getBearing()+p.rotateSpeed*.18,{duration:0});}frame=requestAnimationFrame(cruise);}catch(e){error.value='Mapbox 初始化失败：'+e.message;}}
function dispose(){cancelAnimationFrame(frame);observer?.disconnect();map?.remove();map=null;}
onMounted(init);watch(()=>[props.node.props.mapToken,props.node.props.mapStyle,props.node.props.dem,props.node.props.buildings],()=>{dispose();init();});watch(()=>[props.node.props.lng,props.node.props.lat,props.node.props.zoom,props.node.props.pitch,props.node.props.bearing],()=>{const p=props.node.props;map?.flyTo({center:[p.lng,p.lat],zoom:p.zoom,pitch:p.pitch,bearing:p.bearing,duration:1600});});onBeforeUnmount(dispose);
</script>
<template><div class="aw-map"><template v-if="configured"><div ref="host" class="aw-map-host"></div><div v-if="error" class="aw-map-note">{{error}}</div><div v-if="poi" class="aw-map-popover"><button @click.stop="poi=null">×</button><strong>{{poi.name}}</strong><small>{{poi.lng.toFixed(4)}}, {{poi.lat.toFixed(4)}}</small></div></template><template v-else><SpatialScene :node="node" :theme="theme" :playing="playing" :assets="assets" :interactive="interactive" @action="(...args)=>emit('action',...args)"/><div class="aw-map-note">概念白模地图 · 在右侧配置公开 Mapbox Token 连接地理数据</div></template></div></template>
